{"path": "benchmark_tests/set-priorities.ts", "content": "import {test} from 'node:test';
import assert from 'node:assert/strict';
import PQueue, {
	PriorityQueue,
	type Queue,
	type QueueAddOptions,
	type RunFunction,
} from '../source/index.js';

const tick = async () => new Promise<void>(resolve => {
	setImmediate(resolve);
});

test('setPriorities with an empty batch is a no-op', async () => {
	const runOrder: string[] = [];
	const queue = new PQueue({concurrency: 1, autoStart: false});

	queue.add(() => {
		runOrder.push('a');
	}, {id: 'a', priority: 0});
	queue.add(() => {
		runOrder.push('b');
	}, {id: 'b', priority: 0});

	assert.doesNotThrow(() => {
		queue.setPriorities([]);
	});
	assert.equal(queue.size, 2);

	queue.start();
	await queue.onIdle();

	assert.deepEqual(runOrder, ['a', 'b']);
});

test('setPriorities validates the whole batch before applying any update', async () => {
	const invalidPriorities = [
		NaN,
		Infinity,
		-Infinity,
		'high',
	] as unknown as number[];

	for (const priority of invalidPriorities) {
		const runOrder: string[] = [];
		const queue = new PQueue({concurrency: 1, autoStart: false});

		queue.add(() => {
			runOrder.push('a');
		}, {id: 'a', priority: 0});
		queue.add(() => {
			runOrder.push('b');
		}, {id: 'b', priority: 0});

		assert.throws(() => {
			queue.setPriorities([
				{id: 'b', priority: 9},
				{id: 'a', priority},
			]);
		}, {
			name: 'TypeError',
			message: /Expected `priority` to be a finite number/,
		});

		queue.start();
		await queue.onIdle();

		assert.deepEqual(runOrder, ['a', 'b']);
	}
});

test('setPriorities rejects non-waiting ids before applying any update', async () => {
	let releaseRunning!: () => void;
	const blocker = new Promise<void>(resolve => {
		releaseRunning = resolve;
	});

	const queue = new PQueue({concurrency: 1});
	const running = queue.add(async () => blocker, {id: 'running', priority: 0});
	await tick();

	const runOrder: string[] = [];
	const priorities: Array<number | undefined> = [];
	const waiting = queue.add(() => {
		runOrder.push('waiting');
		priorities.push(queue.runningTasks[0]?.priority);
	}, {id: 'waiting', priority: 0});

	assert.deepEqual(queue.runningTasks.map(({id}) => id), ['running']);

	assert.throws(() => {
		queue.setPriorities([
			{id: 'waiting', priority: 9},
			{id: 'running', priority: 1},
		]);
	}, {
		name: 'ReferenceError',
		message: /No promise function with the id "running" exists in the queue\./,
	});

	assert.throws(() => {
		queue.setPriorities([
			{id: 'waiting', priority: 9},
			{id: 'unknown', priority: 1},
		]);
	}, {
		name: 'ReferenceError',
		message: /No promise function with the id "unknown" exists in the queue\./,
	});

	releaseRunning();
	await running;
	await waiting;

	assert.deepEqual(runOrder, ['waiting']);
	assert.deepEqual(priorities, [0]);
});

test('setPriorities reorders waiting tasks and leaves untouched tasks in FIFO order', async () => {
	const runOrder: string[] = [];
	const queue = new PQueue({concurrency: 1, autoStart: false});

	for (const id of ['a', 'b', 'c', 'd']) {
		queue.add(() => {
			runOrder.push(id);
		}, {id, priority: 0});
	}

	queue.setPriorities([
		{id: 'd', priority: 3},
		{id: 'b', priority: 2},
	]);

	queue.start();
	await queue.onIdle();

	assert.deepEqual(runOrder, ['d', 'b', 'a', 'c']);
});

test('duplicate ids in setPriorities apply in order and the last priority wins', async () => {
	let priorityWhileRunning: number | undefined;
	const queue = new PQueue({concurrency: 1, autoStart: false});

	const task = queue.add(() => {
		priorityWhileRunning = queue.runningTasks[0]?.priority;
	}, {id: 'task', priority: 0});

	queue.setPriorities([
		{id: 'task', priority: 5},
		{id: 'task', priority: -2},
		{id: 'task', priority: 4},
	]);

	queue.start();
	await task;

	assert.equal(priorityWhileRunning, 4);
});

test('setPriorities falls back when the custom queue lacks setPriorities', async () => {
	class FifoQueue implements Queue<RunFunction, QueueAddOptions> {
		readonly #items: Array<{run: RunFunction; id: string | undefined}> = [];

		get size() {
			return this.#items.length;
		}

		enqueue(run: RunFunction, options?: Partial<QueueAddOptions>) {
			this.#items.push({run, id: options?.id});
		}

		dequeue() {
			return this.#items.shift()?.run;
		}

		filter() {
			return this.#items.map(({run}) => run);
		}

		setPriority() {} // eslint-disable-line @typescript-eslint/no-empty-function

		remove(id: string) {
			const index = this.#items.findIndex(item => item.id === id);
			if (index !== -1) {
				this.#items.splice(index, 1);
			}
		}
	}

	const observed: Array<{id: string; priority: number | undefined}> = [];
	const queue = new PQueue({concurrency: 1, autoStart: false, queueClass: FifoQueue});

	queue.add(() => {
		observed.push({
			id: 'first',
			priority: queue.runningTasks.find(({id}) => id === 'first')?.priority,
		});
	}, {id: 'first', priority: 0});
	queue.add(() => {
		observed.push({
			id: 'second',
			priority: queue.runningTasks.find(({id}) => id === 'second')?.priority,
		});
	}, {id: 'second', priority: 0});

	queue.setPriorities([
		{id: 'second', priority: 9},
		{id: 'first', priority: 4},
	]);

	queue.start();
	await queue.onIdle();

	// The custom queue ignores priorities, so tasks still run in FIFO order, but their metadata is updated.
	assert.deepEqual(observed, [
		{id: 'first', priority: 4},
		{id: 'second', priority: 9},
	]);
});

test('PriorityQueue.setPriorities applies updates in order and the last duplicate wins', async () => {
	const queue = new PriorityQueue();

	for (const id of ['a', 'b', 'c']) {
		queue.enqueue(async () => id, {id, priority: 0});
	}

	queue.setPriorities([
		{id: 'c', priority: -1},
		{id: 'c', priority: 2},
		{id: 'b', priority: 1},
	]);

	assert.deepEqual(await Promise.all([
		queue.dequeue()!(),
		queue.dequeue()!(),
		queue.dequeue()!(),
	]), ['c', 'b', 'a']);
});

test('PriorityQueue.setPriorities validates before mutation and treats an empty batch as a no-op', async () => {
	const invalidPriorities = [
		NaN,
		Infinity,
		-Infinity,
		'high',
	] as unknown as number[];

	for (const priority of invalidPriorities) {
		const queue = new PriorityQueue();
		queue.enqueue(async () => 'a', {id: 'a', priority: 0});

		assert.throws(() => {
			queue.setPriorities([
				{id: 'a', priority: 9},
				{id: 'missing', priority},
			]);
		}, {
			name: 'TypeError',
			message: /Expected `priority` to be a finite number/,
		});

		assert.equal(queue.size, 1);
		assert.equal(await queue.dequeue()!(), 'a');
	}

	const queue = new PriorityQueue();
	queue.enqueue(async () => 'a', {id: 'a', priority: 0});
	queue.enqueue(async () => 'b', {id: 'b', priority: 0});

	assert.throws(() => {
		queue.setPriorities([
			{id: 'b', priority: 9},
			{id: 'unknown', priority: 1},
		]);
	}, {
		name: 'ReferenceError',
		message: /No promise function with the id "unknown" exists in the queue\./,
	});

	assert.deepEqual(await Promise.all([
		queue.dequeue()!(),
		queue.dequeue()!(),
	]), ['a', 'b']);

	assert.doesNotThrow(() => {
		queue.setPriorities([]);
	});
});"}

